schema_ddl:
CREATE TABLE fornitori (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE
);

CREATE TABLE flussi_inbound_approvvigionamento (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fornitore_id INT NOT NULL REFERENCES fornitori(id),
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato_ordine TEXT NOT NULL,
    importo_totale NUMERIC(12,2) NOT NULL CHECK (importo_totale >= 0)
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_articolo TEXT NOT NULL UNIQUE,
    descrizione TEXT NOT NULL,
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);

CREATE TABLE dettagli_flusso_inbound (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flusso_inbound_id INT NOT NULL REFERENCES flussi_inbound_approvvigionamento(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_concordato NUMERIC(10,2) NOT NULL CHECK (prezzo_concordato >= 0)
);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    denominazione TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE ordini_cliente (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_emissione DATE NOT NULL DEFAULT CURRENT_DATE,
    stato_ordine TEXT NOT NULL,
    valore_complessivo NUMERIC(12,2) NOT NULL CHECK (valore_complessivo >= 0)
);

CREATE TABLE ordini_cliente_storico (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_emissione DATE NOT NULL,
    stato_ordine TEXT NOT NULL,
    valore_complessivo NUMERIC(12,2) NOT NULL CHECK (valore_complessivo >= 0)
);

CREATE TABLE magazzini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_magazzino TEXT NOT NULL UNIQUE,
    ubicazione TEXT NOT NULL
);

CREATE TABLE giacenze_articoli (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita_disponibile INT NOT NULL CHECK (quantita_disponibile >= 0)
);

CREATE TABLE listini_prezzi (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    fornitore_id INT NOT NULL REFERENCES fornitori(id),
    prezzo_listino NUMERIC(10,2) NOT NULL CHECK (prezzo_listino >= 0)
);

CREATE TABLE transazioni_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flusso_inbound_id INT REFERENCES flussi_inbound_approvvigionamento(id),
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE,
    importo NUMERIC(12,2) NOT NULL,
    stato TEXT NOT NULL
);
